export function localizeSpotlight(spotlight: SpotlightPerson, locale: Locale): SpotlightPerson {
  const copy = editorialByLocale[locale][spotlight.slug];
  const taxonomy = spotlightTaxonomyByLocale[locale][spotlight.slug];
  const cover = spotlight.slug === "evgeny-vinokurov" && spotlight.cover
    ? { ...spotlight.cover, alt: evgenyCoverAlt[locale] }
    : spotlight.cover;
  return { ...spotlight, ...copy, ...taxonomy, cover };
}

export function getLocalizedPublishedSpotlights(locale: Locale): SpotlightPerson[] {
  return publishedSpotlights.map((spotlight) => localizeSpotlight(spotlight, locale));
}

export function getLocalizedPublishedSpotlight(slug: string, locale: Locale): SpotlightPerson | undefined {
  const spotlight = getPublishedSpotlight(slug);
  return spotlight ? localizeSpotlight(spotlight, locale) : undefined;
}

export function getLocalizedRelatedSpotlights(spotlight: SpotlightPerson, locale: Locale): SpotlightPerson[] {
  const source = getPublishedSpotlight(spotlight.slug);
  return source ? getRelatedSpotlights(source).map((related) => localizeSpotlight(related, locale)) : [];
}

